cd /tmp/vally-eval-trial-HcIzrq && cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class LoyaltyDiscountTests
{
    // Gold customer, subtotal 100.00 => payable total 95.00.
    // No checkout/pricing API exists yet, so the outcome cannot be exercised.
    [Fact]
    public void GoldCustomerWithSubtotal100PaysTotal95()
    {
        var types = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => !t.Name.EndsWith("Marker"));

        Assert.True(types.Any(), "No checkout pricing behavior exists; Gold 100.00 -> 95.00 is not produced.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "Failed|Error Message|Assert|No checkout|Passed!" | head

